export function getDetectors(): DetectorEntity[] {
  const all = [...INCIDENTS, ...HEALTHY];
  const refToTrace: Record<string, ObservabilityDemo> = {
    research: H_RESEARCH, checkout: H_CHECKOUT, support: H_SUPPORT,
    stock: H_STOCK, voice: DEMO_I1, billing: DEMO_I3,
  };

  return DETECTOR_DEFS.map((def, di) => {
    // currently-open incidents this detector owns
    const live = INCIDENTS.filter((d) => d.finding.detector === def.type).map((d, i) => ({
      traceId: d.incidentId,
      findingId: `${def.name.replace(/-v1$/, "")}-${String(di)}${String(i)}-${d.traceId.slice(0, 8)}`,
      timestamp: d.startedAt,
      title: d.finding.title,
      severity: d.finding.severity,
      confidence: d.finding.confidence,
      service: d.service,
    }));
    // resolved findings from earlier runs
    const history = (FINDING_HISTORY[def.type] ?? []).map((h) => ({
      traceId: refToTrace[h.traceRef]?.incidentId ?? H_RESEARCH.incidentId,
      findingId: h.findingId,
      timestamp: h.timestamp,
      title: h.title,
      severity: h.severity,
      confidence: h.confidence,
      service: h.service,
      resolved: true,
    }));
    const findings = [...live, ...history];

    // one run row per evaluation: flagged where a finding exists, else clean
    const flaggedTraceIds = new Set(live.map((f) => f.traceId));
    const runs = [
      ...history.map((h) => ({ traceId: h.traceId, timestamp: h.timestamp, identified: true, service: h.service })),
      ...all.map((d) => ({
        traceId: d.incidentId,
        timestamp: d.startedAt,
        identified: flaggedTraceIds.has(d.incidentId),
        service: d.service,
      })),
    ];

    return {
      id: `det-${di}`,
      name: def.name,
      type: def.type,
      description: def.description,
      enabled: true,
      findings,
      runs,
      openFindings: findings.filter((f) => !("resolved" in f && f.resolved)).length,
      totalFindings: findings.length,
      totalRuns: runs.length,
    };
  });
}

export function getDetector(name: string): DetectorEntity | undefined {
  return getDetectors().find((d) => d.name === name);
}

/** Whether a trace exists for this id at all — the gate a route must pass
 *  before calling `getObservabilityDemo`, so an unknown id 404s instead of
 *  quietly rendering the featured incident. */
export function hasObservabilityDemo(incidentId: string): boolean {
  return incidentId in DEMOS;
}

/**
 * Resolve a wire trace id (the short hex on `demo.traceId`) to the incident id
 * the explorer route is actually keyed on.
 *
 * These are two different identifiers and the difference is easy to miss: a
 * demo is stored under a uuid-ish `incidentId`, while `traceId` is what appears
 * on spans and on anything that references a trace from outside — the security
 * capability, for one. Pushing a traceId at /incidents/:id resolves nothing, so
 * every such link 404s. Callers must resolve first and only render the link
 * when this returns non-null.
 */
export function resolveTraceToIncident(traceId: string): string | null {
  if (traceId in DEMOS) return traceId; // already an incident id
  for (const [incidentId, demo] of Object.entries(DEMOS)) {
    if (demo.traceId === traceId) return incidentId;
  }
  return null;
}

/** Coherent rows for the traces list panel — every row opens the trace it names. */
export function getTraceList(): TraceRow[] {
  return TRACE_FEED.map((d) => ({
    id: d.incidentId,
    name: d.spans[0]?.name ?? d.service,
    timestamp: d.startedAt,
    status: d.spans[0]?.status ?? "ok",
    selectable: true,
  }));
}
